CREATE TABLE IF NOT EXISTS users(id SERIAL PRIMARY KEY,name TEXT NOT NULL,email TEXT UNIQUE NOT NULL,phone TEXT NOT NULL,nif TEXT,id_document TEXT,password_hash TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'customer',created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS rates(id SERIAL PRIMARY KEY,currency TEXT UNIQUE NOT NULL,buy_rate NUMERIC(14,2) NOT NULL,sell_rate NUMERIC(14,2) NOT NULL,updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS orders(id SERIAL PRIMARY KEY,reference TEXT UNIQUE NOT NULL,user_id INT REFERENCES users(id),currency TEXT NOT NULL,foreign_amount NUMERIC(14,2) NOT NULL,kwanza_amount NUMERIC(14,2) NOT NULL,rate NUMERIC(14,2) NOT NULL,customer_type TEXT NOT NULL,payment_method TEXT DEFAULT 'bank_transfer',payment_status TEXT DEFAULT 'pending',order_status TEXT DEFAULT 'awaiting_payment',fulfillment TEXT NOT NULL,delivery_address TEXT,withdrawal_location TEXT,withdrawal_code_hash TEXT,withdrawal_code_expires TIMESTAMPTZ,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS payment_proofs(id SERIAL PRIMARY KEY,order_id INT REFERENCES orders(id) ON DELETE CASCADE,filename TEXT NOT NULL,stored_path TEXT NOT NULL,uploaded_at TIMESTAMPTZ DEFAULT NOW());
